Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>Elapsed time after opening stopcock: <output id="elapsedTimeVal">0</output><input id="elapsedTimeInput" type="range" min="0" max="100" step="1" value="0" oninput="document.getElementById('elapsedTimeVal').value=this.value;update_elapsedTime(+this.value)"></label>
<button id="playDiffusionInput" onclick="trigger_playDiffusion()">Animate diffusion</button>
<label><input id="massCodingInput" type="checkbox" onchange="toggle_massCoding(this.checked)"> Mass emphasis</label>
<span id="demoNarration" style="margin:0;font-size:10px;max-width:180px">With the stopcock closed, H2 molecules are confined to the left bulb and O2 molecules are confined to the right bulb. No mixing occurs because the valve blocks particle exchange.</span>
<span><button onclick="prevStep()">◀</button> <span id="stepLabel">1 / 4: Separated gases</span> <button onclick="nextStep()">▶</button></span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, 1280, 340);

var state = {
  elapsedTime: 0,
  massCoding: false,
  step: 0,
  playing: false,
  timer: null
};

var demoSteps = [
  {
    title: 'Separated gases',
    narration: 'With the stopcock closed, H2 molecules are confined to the left bulb and O2 molecules are confined to the right bulb. No mixing occurs because the valve blocks particle exchange.',
    state: { elapsedTime: 0, massCoding: 'Normal colors' }
  },
  {
    title: 'Just after opening',
    narration: 'When the stopcock opens, particles begin moving through the connecting tube. More H2 appears on the oxygen side than O2 appears on the hydrogen side because lighter H2 diffuses faster.',
    state: { elapsedTime: 25, massCoding: 'Color-code by molecular mass' }
  },
  {
    title: 'Approaching uniform mixture',
    narration: 'As time passes, both gases spread through both bulbs. The concentration gradients shrink, so the visible net change slows even though molecules continue moving randomly.',
    state: { elapsedTime: 70, massCoding: 'Color-code by molecular mass' }
  },
  {
    title: 'After diffusion',
    narration: 'Eventually both H2 and O2 are distributed approximately uniformly across the two bulbs. The gases are mixed, and there is no longer a strong concentration gradient driving net redistribution.',
    state: { elapsedTime: 100, massCoding: 'Normal colors' }
  }
];

var leftPts = [
  [-44,-58],[-8,-68],[30,-56],[58,-35],[-66,-32],[-34,-12],[4,-18],[42,-8],
  [68,4],[-56,18],[-22,18],[18,12],[52,28],[-43,45],[-5,44],[36,51],
  [-66,56],[-10,-42],[-74,0],[66,45],[2,34],[28,-30]
];
var leftAltPts = [
  [-25,-56],[16,-64],[50,-48],[-58,-21],[-16,-20],[26,-16],[58,-2],
  [-70,24],[-36,20],[5,22],[42,18],[-50,50],[-12,56],[24,48],[60,42],
  [-2,-2],[72,20],[-76,-48],[14,64],[44,-34],[-42,-2],[8,-38]
];

function mirrorPts(pts) {
  return pts.map(function (p) { return [-p[0], p[1]]; });
}
var rightPts = mirrorPts(leftAltPts);
var rightAltPts = mirrorPts(leftPts);

function smoother(t) {
  t = Math.max(0, Math.min(1, t));
  return t * t * (3 - 2 * t);
}

function h2CrossCount(t, n) {
  var f = 0.5 * (1 - Math.exp(-t / 20)) / (1 - Math.exp(-100 / 20));
  return Math.min(Math.floor(n / 2), Math.round(n * f));
}

function o2CrossCount(t, n) {
  var f = 0.5 * (1 - Math.exp(-t / 55)) / (1 - Math.exp(-100 / 55));
  return Math.min(Math.floor(n / 2), Math.round(n * f));
}

function addTooltip(el, title, body) {
  el.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(title, e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () { showPopup(title, body); });
}

function textWithHalo(txt) {
  txt.attr({
    'paint-order': 'stroke',
    stroke: '#ffffff',
    'stroke-width': 4,
    'stroke-linejoin': 'round'
  });
  return txt;
}

function labelBox(g, x, y, text, color, anchor) {
  var t = g.text(text).font({ family: 'sans-serif', size: 17, anchor: anchor || 'middle' }).fill(color);
  textWithHalo(t);
  t.center(x, y);
  var b = t.bbox();
  g.rect(b.width + 12, b.height + 6).move(b.x - 6, b.y - 3).fill({ color: '#ffffff', opacity: 0.78 }).stroke('none').back();
  return t;
}

function arrow(g, x1, y1, x2, y2, color, width) {
  var ln = g.line(x1, y1, x2, y2).stroke({ color: color, width: width, linecap: 'round' }).opacity(0.78);
  var ang = Math.atan2(y2 - y1, x2 - x1);
  var len = 13, spread = 0.55;
  var p1 = [x2, y2];
  var p2 = [x2 - len * Math.cos(ang - spread), y2 - len * Math.sin(ang - spread)];
  var p3 = [x2 - len * Math.cos(ang + spread), y2 - len * Math.sin(ang + spread)];
  g.polygon([p1, p2, p3].map(function (p) { return p[0] + ',' + p[1]; }).join(' '))
    .fill(color).opacity(0.78);
  return ln;
}

function drawValve(g, cx, cy, open) {
  var glassStroke = '#9cc8c9';
  g.ellipse(48, 13).center(cx, cy - 45).fill({ color: '#dceff0', opacity: 0.72 }).stroke({ color: glassStroke, width: 4 });
  g.line(cx - 14, cy - 38, cx + 14, cy - 20).stroke({ color: glassStroke, width: 4, linecap: 'round' });
  g.line(cx + 14, cy - 38, cx - 14, cy - 20).stroke({ color: glassStroke, width: 4, linecap: 'round' });
  g.rect(34, 18).center(cx, cy - 18).radius(5).fill({ color: '#dceff0', opacity: 0.72 }).stroke({ color: glassStroke, width: 4 });

  g.rect(32, 58).center(cx, cy + 2).radius(5).fill({ color: '#dceff0', opacity: 0.78 }).stroke({ color: glassStroke, width: 4 });
  if (open) {
    g.line(cx - 18, cy + 2, cx + 18, cy + 2).stroke({ color: glassStroke, width: 7, linecap: 'round' });
    g.circle(8).center(cx, cy + 2).fill('#ffffff').opacity(0.8);
  } else {
    g.rect(14, 48).center(cx, cy + 2).radius(3).fill({ color: '#8fbec1', opacity: 0.78 }).stroke({ color: glassStroke, width: 2 });
  }
  g.rect(21, 16).center(cx, cy + 43).fill({ color: '#dceff0', opacity: 0.78 }).stroke({ color: glassStroke, width: 4 });
}

function drawGlass(g, base, open) {
  var cy = 128;
  var cL = base + 104;
  var cR = base + 300;
  var r = 82;
  var glassFill = '#dceff0';
  var glassStroke = '#9cc8c9';

  g.rect(cR - r - (cL + r) + 12, 38).move(cL + r - 6, cy - 19)
    .radius(18).fill({ color: glassFill, opacity: 0.74 })
    .stroke({ color: glassStroke, width: 5 });

  g.circle(r * 2).center(cL, cy)
    .fill({ color: glassFill, opacity: 0.82 })
    .stroke({ color: glassStroke, width: 5 });
  g.circle(r * 2).center(cR, cy)
    .fill({ color: glassFill, opacity: 0.82 })
    .stroke({ color: glassStroke, width: 5 });

  g.circle(13).center(cL - 42, cy - 68).fill('#ffffff').opacity(0.75);
  g.circle(10).center(cL - 68, cy - 32).fill('#ffffff').opacity(0.45);
  g.circle(13).center(cR - 42, cy - 68).fill('#ffffff').opacity(0.75);
  g.circle(10).center(cR - 68, cy - 32).fill('#ffffff').opacity(0.45);

  drawValve(g, (cL + cR) / 2, cy, open);
  return { cL: cL, cR: cR, cy: cy, r: r, valveX: (cL + cR) / 2 };
}

function drawMolecule(g, x, y, type, emphasized) {
  var isH = type === 'H2';
  var fill = isH ? '#ffffff' : '#d81a0c';
  var halo = isH ? '#4fc3d8' : '#f1913a';
  if (emphasized) {
    g.circle(isH ? 17 : 15).center(x, y).fill('none').stroke({ color: halo, width: isH ? 2.2 : 1.4 }).opacity(isH ? 0.68 : 0.5);
  }
  var c = g.circle(isH ? 12 : 11).center(x, y)
    .fill(fill)
    .stroke(isH ? { color: '#ffffff', width: 1 } : 'none');
  if (isH) c.opacity(0.96);
  addTooltip(
    c,
    isH ? 'H₂ molecule: light and fast' : 'O₂ molecule: heavier and slower',
    isH
      ? 'Hydrogen molecules have much lower molecular mass, so their average speed is higher at the same temperature. They diffuse into the other bulb faster.'
      : 'Oxygen molecules are heavier, so their average speed is lower at the same temperature. They still diffuse, but more slowly than H₂.'
  );
}

function addParticles(g, geom, t, emphasized, forceClosed) {
  var n = 20;
  var openT = forceClosed ? 0 : t;
  var hRight = h2CrossCount(openT, n);
  var oLeft = o2CrossCount(openT, n);

  for (var i = 0; i < n - hRight; i++) drawMolecule(g, geom.cL + leftPts[i][0], geom.cy + leftPts[i][1], 'H2', emphasized);
  for (var j = 0; j < hRight; j++) drawMolecule(g, geom.cR + rightPts[j][0], geom.cy + rightPts[j][1], 'H2', emphasized);

  for (var k = 0; k < oLeft; k++) drawMolecule(g, geom.cL + leftAltPts[k][0], geom.cy + leftAltPts[k][1], 'O2', emphasized);
  for (var m = 0; m < n - oLeft; m++) drawMolecule(g, geom.cR + rightAltPts[m][0], geom.cy + rightAltPts[m][1], 'O2', emphasized);

  if (!forceClosed && openT > 4 && openT < 80) {
    var p = smoother(openT / 80);
    var xH = geom.valveX - 48 + 96 * Math.min(1, p * 1.45);
    var xO = geom.valveX + 44 - 76 * Math.min(1, p * 0.9);
    drawMolecule(g, xH, geom.cy - 5, 'H2', emphasized);
    if (openT > 15) drawMolecule(g, xO, geom.cy + 10, 'O2', emphasized);
  }
}

function drawCaption(g, x, y, lines, panel) {
  var txt = g.text(function (add) {
    for (var i = 0; i < lines.length; i++) {
      var sp = add.tspan(lines[i]);
      if (i < lines.length - 1) sp.newLine();
    }
  }).font({ family: 'sans-serif', size: 25, anchor: 'middle' }).fill('#000000');
  txt.center(x, y);
  textWithHalo(txt);
  var p = g.text(panel).font({ family: 'sans-serif', size: 24, anchor: 'middle' }).fill('#000000');
  p.center(x, y + (lines.length > 1 ? 48 : 36));
  textWithHalo(p);
}

function drawMassCues(g, base, geom, t) {
  if (!state.massCoding) return;
  arrow(g, geom.valveX - 92, geom.cy - 43, geom.valveX + 82, geom.cy - 43, '#4fc3d8', 4);
  arrow(g, geom.valveX + 72, geom.cy + 45, geom.valveX + 8, geom.cy + 45, '#f1913a', 3);
  labelBox(g, geom.valveX - 55, geom.cy - 72, 'light H₂: faster', '#168fa3', 'middle');
  labelBox(g, geom.valveX + 72, geom.cy + 73, 'heavy O₂: slower', '#b54f00', 'middle');
}

function drawPanel(base, t, panelType, panelLabel) {
  var g = draw.group();
  var open = panelType !== 'closed' && t > 0;
  if (panelType === 'final') open = true;
  var geom = drawGlass(g, base, open);

  if (panelType === 'current') drawMassCues(g, base, geom, t);

  if (panelType === 'closed') addParticles(g, geom, 0, state.massCoding, true);
  else addParticles(g, geom, t, state.massCoding, false);

  var hot = g.rect(170, 110).center(geom.valveX, geom.cy).fill({ color: '#fff', opacity: 0 });
  addTooltip(
    hot,
    open ? 'Stopcock open: gases can exchange' : 'Stopcock closed: gases are separated',
    open
      ? 'Opening the valve allows molecules from each high-concentration side to enter the other side. Individual paths are random, but the net effect is spreading.'
      : 'With the valve closed, molecules still move randomly inside each bulb, but the barrier prevents diffusion between bulbs.'
  );

  return geom;
}

function render() {
  draw.clear();
  draw.rect(1280, 340).fill('#ffffff');

  var t = state.elapsedTime;
  var finalT = 100;

  var gA = drawPanel(2, 0, 'closed', '(a)');
  var gB = drawPanel(432, t, t === 0 ? 'closed' : 'current', '(b)');
  var gC = drawPanel(862, finalT, 'final', '(c)');

  var h2 = draw.text('H₂').font({ family: 'sans-serif', size: 27, anchor: 'middle' }).fill('#000000');
  h2.center(gA.cL, 16);
  textWithHalo(h2);
  var o2 = draw.text('O₂').font({ family: 'sans-serif', size: 27, anchor: 'middle' }).fill('#000000');
  o2.center(gA.cR, 16);
  textWithHalo(o2);

  drawCaption(draw, 202, 286, ['Stopcock closed'], '(a)');
  drawCaption(draw, 632, 286, ['Stopcock open'], '(b)');
  drawCaption(draw, 1062, 273, ['Some time after', 'Stopcock open'], '(c)');

  var panelBOverlay = draw.rect(404, 326).move(430, 7).fill('none')
    .stroke({ color: t === 0 ? '#6f8790' : '#4aa5c0', width: 2, dasharray: '7,6' }).opacity(0.55);
  addTooltip(
    panelBOverlay,
    'Interactive panel',
    'The middle apparatus responds to the elapsed-time slider. Notice that H₂ crosses into the right bulb earlier than O₂ crosses into the left bulb.'
  );
}

function setStep(i) {
  state.step = (i + demoSteps.length) % demoSteps.length;
  var step = demoSteps[state.step];
  var t = step.state.elapsedTime;
  var mass = step.state.massCoding === 'Color-code by molecular mass';

  document.getElementById('elapsedTimeInput').value = t;
  document.getElementById('elapsedTimeVal').value = t;
  document.getElementById('massCodingInput').checked = mass;
  document.getElementById('demoNarration').textContent = step.narration;
  document.getElementById('stepLabel').textContent = (state.step + 1) + ' / ' + demoSteps.length + ': ' + step.title;

  state.elapsedTime = t;
  state.massCoding = mass;
  stopAnimation();
  render();
}

function stopAnimation() {
  if (state.timer) clearInterval(state.timer);
  state.timer = null;
  state.playing = false;
  var btn = document.getElementById('playDiffusionInput');
  if (btn) btn.textContent = 'Animate diffusion';
}

window.update_elapsedTime = function (v) {
  state.elapsedTime = Math.max(0, Math.min(100, v));
  render();
};

window.toggle_massCoding = function (on) {
  state.massCoding = !!on;
  render();
};

window.trigger_playDiffusion = function () {
  if (state.playing) {
    stopAnimation();
    return;
  }
  state.playing = true;
  var btn = document.getElementById('playDiffusionInput');
