function smoother(t) {
  t = Math.max(0, Math.min(1, t));
  return t * t * (3 - 2 * t);
}

function h2CrossCount(t, n) {
  var f = 0.5 * (1 - Math.exp(-t / 20)) / (1 - Math.exp(-100 / 20));
  return Math.min(Math.floor(n / 2), Math.round(n * f));
}

