function txtHalo(t, width) {
  t.attr({
    'paint-order': 'stroke',
    stroke: '#ffffff',
    'stroke-width': width || 4,
    'stroke-linejoin': 'round'
  });
  return t;
}

function addPanelText(text, x, y, size, anchor) {
  var t = draw.text(text).font({ family: 'sans-serif', size: size, anchor: anchor || 'middle' }).fill('#000000');
  t.center(x, y);
  txtHalo(t, 4);
  return t;
}

function addCaption(x, y, lines, panelLabel) {
  for (var i = 0; i < lines.length; i++) {
    addPanelText(lines[i], x, y + i * 31, 25, 'middle');
  }
  addPanelText(panelLabel, x, y + lines.length * 31 + 8, 23, 'middle');
}

function drawValve(g, cx, cy, open) {
  var glassStroke = '#98c4c6';
  var glassFill = '#d9eeee';

  g.ellipse(52, 13).center(cx, cy - 47)
    .fill({ color: glassFill, opacity: 0.72 })
    .stroke({ color: glassStroke, width: 5 });

  g.line(cx - 16, cy - 42, cx - 8, cy - 28)
    .stroke({ color: glassStroke, width: 5, linecap: 'round' });
  g.line(cx + 16, cy - 42, cx + 8, cy - 28)
    .stroke({ color: glassStroke, width: 5, linecap: 'round' });

  g.rect(43, 13).center(cx, cy - 24).radius(4)
    .fill({ color: glassFill, opacity: 0.78 })
    .stroke({ color: glassStroke, width: 5 });

  g.rect(27, 58).center(cx, cy + 2).radius(4)
    .fill({ color: glassFill, opacity: 0.83 })
    .stroke({ color: glassStroke, width: 5 });

  if (open) {
    g.line(cx - 19, cy + 2, cx + 19, cy + 2)
      .stroke({ color: '#ffffff', width: 8, linecap: 'round', opacity: 0.72 });
    g.line(cx - 15, cy + 2, cx + 15, cy + 2)
      .stroke({ color: glassStroke, width: 3, linecap: 'round', opacity: 0.75 });
  } else {
    g.rect(11, 48).center(cx, cy + 2).radius(3)
      .fill({ color: '#8fbec1', opacity: 0.86 })
      .stroke({ color: glassStroke, width: 2 });
  }

  g.rect(22, 14).center(cx, cy + 43).radius(1)
    .fill({ color: glassFill, opacity: 0.8 })
    .stroke({ color: glassStroke, width: 5 });
}

function drawGlass(g, base, open) {
  var cy = 130;
  var cL = base + 88;
  var cR = base + 340;
  var r = 88;
  var glassFill = '#d9eeee';
  var glassStroke = '#98c4c6';

  var tubeX = cL + r - 10;
  var tubeW = cR - cL - 2 * r + 20;
  g.rect(tubeW, 35).move(tubeX, cy - 17.5)
    .radius(17)
    .fill({ color: glassFill, opacity: 0.78 })
    .stroke({ color: glassStroke, width: 5 });

  g.circle(2 * r).center(cL, cy)
    .fill({ color: glassFill, opacity: 0.82 })
    .stroke({ color: glassStroke, width: 5 });
  g.circle(2 * r).center(cR, cy)
    .fill({ color: glassFill, opacity: 0.82 })
    .stroke({ color: glassStroke, width: 5 });

  g.circle(13).center(cL - 43, cy - 71).fill('#ffffff').opacity(0.72);
  g.circle(10).center(cL - 70, cy - 34).fill('#ffffff').opacity(0.43);
  g.circle(13).center(cR - 43, cy - 71).fill('#ffffff').opacity(0.72);
  g.circle(10).center(cR - 70, cy - 34).fill('#ffffff').opacity(0.43);

  drawValve(g, (cL + cR) / 2, cy, open);
  return { cL: cL, cR: cR, cy: cy, r: r, valveX: (cL + cR) / 2 };
}

function addMolecule(g, x, y, kind) {
  var isH = kind === 'H2';
  return g.circle(isH ? 12.5 : 11.5).center(x, y)
    .fill(isH ? '#ffffff' : '#d81a0c')
    .opacity(isH ? 0.96 : 1);
}

function addDots(g, centerX, centerY, list, kind) {
  for (var i = 0; i < list.length; i++) {
    addMolecule(g, centerX + list[i][0], centerY + list[i][1], kind);
  }
}

function addTubeDots(g, geom, dots) {
  for (var i = 0; i < dots.length; i++) {
    addMolecule(g, geom.valveX + dots[i][0], geom.cy + dots[i][1], dots[i][2]);
  }
}

function focusOpacity(name) {
  if (state.stageFocus === 'allPanels') return 1;
  return state.stageFocus === name ? 1 : 0.25;
}

function addHoverRegion(g, name, geom, title, body) {
  if (state.stageFocus === name) {
    g.rect(430, 222).move(geom.cL - 101, 21).radius(13)
      .fill({ color: '#b7dadd', opacity: 0.11 })
      .stroke({ color: '#74aeb3', width: 3, opacity: 0.42 })
      .back();
  }

  var hover = g.rect(430, 222).move(geom.cL - 101, 21).fill({ color: '#ffffff', opacity: 0 });
  hover.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(title, e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () { showPopup(title, body); });
}

function drawPanel(name) {
  var base = bases[name];
  var g = draw.group().opacity(focusOpacity(name));
  var open = name !== 'closed';
  var geom = drawGlass(g, base, open);

  if (name === 'closed') {
    addDots(g, geom.cL, geom.cy, hInitial, 'H2');
    addDots(g, geom.cR, geom.cy, oInitial, 'O2');
    addTubeDots(g, geom, [[-48, -1, 'H2'], [-28, 1, 'H2'], [36, 2, 'O2']]);
    addHoverRegion(
      g, name, geom,
      'Panel (a): stopcock closed',
      'The gases are separated because the closed stopcock blocks exchange between bulbs. Molecules still move randomly inside each bulb and neck region, but they cannot pass through the valve.'
    );
  }

  if (name === 'justOpened') {
    addDots(g, geom.cL, geom.cy, hBLeft, 'H2');
    addDots(g, geom.cR, geom.cy, hBRight, 'H2');
    addDots(g, geom.cL, geom.cy, oBLeft, 'O2');
    addDots(g, geom.cR, geom.cy, oBRight, 'O2');
    addTubeDots(g, geom, [[-50, 2, 'H2'], [-25, -1, 'H2'], [23, 1, 'O2'], [51, 0, 'O2']]);
    addHoverRegion(
      g, name, geom,
      'Panel (b): stopcock open',
      'Opening the stopcock gives molecules a path through the tube. H₂ is still concentrated on the left and O₂ on the right, but some particles of each gas have already diffused to the other side.'
    );
  }

  if (name === 'laterMixed') {
    addDots(g, geom.cL, geom.cy, hCL, 'H2');
    addDots(g, geom.cR, geom.cy, hCR, 'H2');
    addDots(g, geom.cL, geom.cy, oCL, 'O2');
    addDots(g, geom.cR, geom.cy, oCR, 'O2');
    addTubeDots(g, geom, [[-53, -1, 'O2'], [-27, 2, 'H2'], [0, 0, 'O2'], [27, -2, 'H2'], [54, 1, 'O2']]);
    addHoverRegion(
      g, name, geom,
      'Panel (c): some time after opening',
      'After more time, both gases are distributed throughout the connected bulbs and tube. The gases do not sort back into separate sides; random motion produces a mixed distribution.'
    );
  }

  return geom;
}

function render() {
  draw.clear();
  draw.rect(1290, 340).fill('#ffffff');

  var a = drawPanel('closed');
  var b = drawPanel('justOpened');
  var c = drawPanel('laterMixed');

  addPanelText('H₂', a.cL, 15, 25, 'middle');
  addPanelText('O₂', a.cR, 15, 25, 'middle');

  addCaption((a.cL + a.cR) / 2, 286, ['Stopcock closed'], '(a)');
  addCaption((b.cL + b.cR) / 2, 286, ['Stopcock open'], '(b)');
  addCaption((c.cL + c.cR) / 2, 254, ['Some time after', 'Stopcock open'], '(c)');
}

window.update_stageFocus = function (v) {
  state.stageFocus = v;
  render();
};

function setStep(i) {
  state.step = (i + demoSteps.length) % demoSteps.length;
  var step = demoSteps[state.step];
  state.stageFocus = step.state.stageFocus;

  var input = document.getElementById('stageFocusInput');
  if (input) input.value = state.stageFocus;

  document.getElementById('demoNarration').textContent = step.narration;
  document.getElementById('stepLabel').textContent = (state.step + 1) + ' / ' + demoSteps.length + ': ' + step.title;
  render();
}

window.prevStep = function () {
  setStep(state.step - 1);
};

window.nextStep = function () {
  setStep(state.step + 1);
};

setStep(0);
window.__markRendered();
